import itertools, json
jobs='ABCDE'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
trans=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def nominal(r):
 return sum(slot[j][i] for i,j in enumerate(r))+sum(trans[a][jobs.index(b)] for a,b in zip(r,r[1:]))
def incident(r,s):
 p={j:r.index(j)+1 for j in jobs}
 if p['A']>=p['D']: return None
 if s=='rain':
  if p['C']==5 or p['A']==1: return None
  return nominal(r)+8*(p['E']-1)
 if s=='road':
  if p['B']==1 or p['C']==2: return None
  return nominal(r)+5*max(0,p['D']-3)
 if s=='lift':
  if p['D']==5 or p['B']==5: return None
  return nominal(r)+5*max(0,p['E']-2)
def neighborhood(r):
 yield r,0
 for i,j in itertools.combinations(range(5),2):
  q=list(r);q[i],q[j]=q[j],q[i]
  yield ''.join(q),1
records=[]
for perm in itertools.permutations(jobs):
 r=''.join(perm)
 if r.index('A')>r.index('D'):continue
 best={}
 for s in ['rain','road','lift']:
  opts=[(incident(q,s)+ex,q) for q,ex in neighborhood(r) if incident(q,s) is not None]
  if not opts:break
  best[s]=min(opts)
 if len(best)==3:records.append((nominal(r)+max(c for c,q in best.values()),r,best))
records.sort()
score,r,best=records[0]
answer={'roster':r,'score':score,'repairs':{s:q for s,(c,q) in best.items()},'repair_costs':{s:c for s,(c,q) in best.items()},'feasible_count':len(records),'next_score':min(c for c,_,_ in records if c>score)}
payload=json.dumps(answer,separators=(',',':'))
# Independent full-pair scan uses Hamming distance to recognize a single swap.
valid=[''.join(p) for p in itertools.permutations(jobs) if p.index('A')<p.index('D')]
rows=[]
for pub in valid:
 costs={}
 for s in ['rain','road','lift']:
  candidates=[]
  for final in valid:
   d=sum(a!=b for a,b in zip(pub,final))
   if d not in (0,2):continue
   pos=lambda j: final.index(j)+1
   forbidden={'rain':pos('C')==5 or pos('A')==1,'road':pos('B')==1 or pos('C')==2,'lift':pos('D')==5 or pos('B')==5}[s]
   if forbidden:continue
   penalty={'rain':8*(pos('E')-1),'road':5*max(pos('D')-3,0),'lift':5*max(pos('E')-2,0)}[s]
   base=sum(slot[final[k]][k] for k in range(5))+sum(trans[final[k]][ord(final[k+1])-ord('A')] for k in range(4))
   candidates.append((base+penalty+(d==2),final))
  if candidates:costs[s]=min(candidates)
 if len(costs)==3:rows.append((nominal(pub)+max(v[0] for v in costs.values()),pub,costs))
assert sorted(rows)==records
out=json.loads(payload)
assert out['score']==min(x[0] for x in rows)
assert out['feasible_count']==len(rows)
assert out['next_score']==min(x[0] for x in rows if x[0]>out['score'])
chosen=next(x for x in rows if x[1]==out['roster'])
for s in ['rain','road','lift']:
 assert (out['repair_costs'][s],out['repairs'][s])==chosen[2][s]
print(payload)
print('Verified by independent full-pair enumeration; published nominal:',nominal(r))

