import itertools,json
jobs='ABCDE'; start='EABDC'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
t=[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]
def neighbors(r):
 for i,j in itertools.combinations(range(5),2):
  q=list(r);q[i],q[j]=q[j],q[i];yield ''.join(q)
dist={start:0}
for d in range(2):
 for r in [r for r,v in dist.items() if v==d]:
  for q in neighbors(r):
   if q not in dist:dist[q]=d+1
def legal(r):return r.index('A')<r.index('D') and r[4]!='C' and r[0] not in 'AE'
def cost(r,d):
 return sum(slot[j][i] for i,j in enumerate(r))+sum(t[jobs.index(a)][jobs.index(b)] for a,b in zip(r,r[1:]))+8*r.index('E')+d+10*(d==2)
classes={d:sorted((cost(r,d),r) for r,v in dist.items() if v==d and legal(r)) for d in range(3)}
best=min(x for c in classes.values() for x in c)
answer={'roster':best[1],'score':best[0],'best_by_swaps':{str(d):c[0][0] if c else None for d,c in classes.items()},'feasible_by_swaps':{str(d):len(c) for d,c in classes.items()}}
payload=json.dumps(answer,separators=(',',':'))
# Independent distance: n minus cycle count of the position permutation.
check={d:[] for d in range(3)}
for p in itertools.permutations(jobs):
 r=''.join(p); perm=[start.index(j) for j in r];seen=set();cycles=0
 for i in range(5):
  if i in seen:continue
  cycles+=1;k=i
  while k not in seen:seen.add(k);k=perm[k]
 d=5-cycles
 if d<=2:
  assert dist[r]==d
  if legal(r):check[d].append((cost(r,d),r))
assert all(sorted(check[d])==classes[d] for d in range(3))
out=json.loads(payload)
assert (out['score'],out['roster'])==min(x for c in check.values() for x in c)
assert out['best_by_swaps']=={str(d):min(c)[0] if c else None for d,c in check.items()}
assert out['feasible_by_swaps']=={str(d):len(c) for d,c in check.items()}
print(payload)
print('Verified BFS exchange distances against cycle-count distances for all permutations.')

